from lesson_authoring import entry as E
B=[['拉丁 optimus／其中性形式 optimum','最好的；最佳者']]
W=[
E('optimal','英 /ˈɒptɪməl/；美 /ˈɑptɪməl/','最佳的；最合适的','像调烤箱：温度太低不熟，太高烤焦，适合当前食物的那个档位才是最佳。','optimum 的 optim- 词干 + -al；最终来自拉丁 optimus“最好”。',B+[['英语 optimum → optimal','最佳状态 → 最佳的']],'optimal conditions 是最有利于某个目标的条件；an optimal solution 是在指定规则下最好的解。这里的“最好”要看目标和限制，未必意味着最快、最大或最贵。','optimal conditions；an optimal solution；optimal performance。','optimal 是形容词；optimum 既可作名词也可作形容词。maximum 只说最大值，不保证最合适。',('We tested several settings to find the optimal temperature.','我们测试了几种设置，寻找最合适的温度。'),('The fastest route is not always optimal if you want to avoid tolls.','如果想避开收费路段，最快的路线未必是最佳路线。'),sources=['https://www.merriam-webster.com/dictionary/optimal','https://www.etymonline.com/word/optimal']),
E('optimum','英 /ˈɒptɪməm/；美 /ˈɑptɪməm/','最佳状态；最适值；最佳的','在一排可选位置中，圈出对目标最有利的那个点。','借入拉丁 optimus 的中性形式 optimum；近代科学用它表示最有利的条件或数值。',B+[['近代拉丁 optimum → 英语 optimum','最有利的条件、数量或状态']],'reach an optimum 是达到最佳点；an optimum temperature 是最适温度。名词复数可用 optima 或 optimums。别把它理解成无条件的完美：换了目标，最佳点也可能变化。','reach the optimum；an optimum level；the optimum for growth。','the optimum 可独立作名词，the optimal 通常需后接名词或有明确省略语境。两者作形容词时常可互换。',('The experiment helped us identify the optimum for this process.','实验帮助我们找到了这一过程的最佳点。'),('Each plant has its own optimum range of growing conditions.','每种植物都有各自最适宜的生长条件范围。'),sources=['https://www.etymonline.com/word/optimum','https://www.merriam-webster.com/dictionary/optimum']),
E('optimally','英 /ˈɒptɪməli/；美 /ˈɑptɪməli/','以最佳方式；处于最佳状态地','不是只问机器有没有转，而是问它有没有在最适合的状态下转。','optimal 最佳的 + -ly，变成描述运作方式的副词。',B+[['optimum → optimal → optimally','最佳状态 → 最佳的 → 以最佳方式']],'function optimally 是发挥最佳作用；optimally positioned 是放在最合适的位置。它常修饰运行、安排和分配，强调在给定条件下达到理想表现。','function optimally；perform optimally；optimally positioned。','optimally 说实际或目标中的最佳表现；optimistically 说一个人的乐观看法，不能互换。',('The system works optimally when the workload is evenly distributed.','工作负载均匀分配时，系统运行得最好。'),('The speakers are optimally positioned for this room.','扬声器放在了最适合这个房间的位置。'),sources=['https://www.merriam-webster.com/dictionary/optimally','https://en.wiktionary.org/wiki/optimally']),
E('optimality','英 /ˌɒptɪˈmæləti/；美 /ˌɑptɪˈmæləti/','最优性；达到最佳的性质','已经找到了一个能用的答案，再问：有没有证据说明它是允许范围内最好的？','optimal 最佳的 + -ity 状态、性质；重音移到 -mal- 这一节。',B+[['optimum → optimal → optimality','最佳状态 → 最佳的 → 最优性']],'prove optimality 是证明没有符合条件的方案能更好；optimality conditions 是判断最优性所用的条件。这个词常见于数学、算法和优化讨论，日常评价一般直接说 best。','prove optimality；conditions for optimality；global optimality。','feasibility 问能否满足约束，optimality 问在满足约束的方案里是否最好。找到可行解不等于证明最优。',('The algorithm finds a feasible solution but does not guarantee optimality.','算法能找到可行解，但不保证最优。'),('The final section gives a proof of optimality.','最后一节给出了最优性的证明。'),sources=['https://www.merriam-webster.com/dictionary/optimality','https://en.wiktionary.org/wiki/optimality']),
E('optimize','英 /ˈɒptɪmaɪz/；美 /ˈɑptɪmaɪz/','优化；使尽可能有效','像调一组旋钮，让有限的时间、电量或空间用得更合适。','现代可认 optim- 最好 + -ize 使成为。早期词史与 optimist／optimism 相连；不是从较晚出现的英语 optimal 直接加后缀。',B+[['optimist／optimism 词族与早期 optimize','乐观看待；尽量发挥'],['现代 optimize','按目标调整，使尽可能有效']],'optimize a route 是按时间、距离等目标调整路线；optimize for speed 是优先为速度优化。它不保证每项指标都提升：速度提高可能伴随内存增加。词源资料对最初构词细节有不同分析，但都接“最好”这条词族。','optimize performance；optimize resource use；optimize for speed。','improve 是一般变好；optimize 常强调针对目标调整。maximize 是使某数值最大，只有目标正好是最大化时才一致。',('We optimized the route to reduce unnecessary travel.','我们优化了路线，减少不必要的路程。'),('The program is optimized for speed rather than minimal memory use.','这个程序优先优化速度，而不是尽量少用内存。'),sources=['https://www.etymonline.com/word/optimize','https://www.merriam-webster.com/dictionary/optimize','https://en.wiktionary.org/wiki/optimize']),
E('optimise','英 /ˈɒptɪmaɪz/；美 /ˈɑptɪmaɪz/','优化〔常见英式拼写〕','把现有条件重新调配，让它们更接近想要的结果。','与 optimize 同词，-ise 是常见英式拼写；optim- 仍表示最好。',B+[['英语 optimize／optimise','历史同属“最好”词族；现代表示优化']],'optimise the layout 可以指调整桌椅、按钮或仓库布局，让使用更顺。英式英语也使用 optimize，不能见到 z 就判错；同一篇文章最好保持拼写体系一致。','optimise the layout；optimise efficiency；optimise for mobile devices。','optimise 与 optimize 意义和读音相同；它不是另一种更强或更弱的优化。',('We rearranged the shelves to optimise the use of space.','我们重新摆放了架子，以更好地利用空间。'),('The team will optimise the page for smaller screens.','团队将针对小屏幕优化这个页面。'),sources=['https://en.wiktionary.org/wiki/optimise','https://www.etymonline.com/word/optimize']),
E('optimization','英 /ˌɒptɪmaɪˈzeɪʃən/；美 /ˌɑptɪməˈzeɪʃən/','优化；寻求最优方案的过程','把“调得更合适”这项工作整体装进一个名词里。','optimize + -ation；词尾形成 -ization，表示过程。',B+[['英语 optimize → optimization','优化 → 优化过程']],'route optimization 说路线优化；performance optimization 说性能优化。专业问题通常要说清优化目标和约束，例如时间更少但费用不能超标，否则“最优”没有明确参照。','performance optimization；route optimization；an optimization problem。','optimization 是过程，optimum 是理想点或最佳状态。做过优化，不等于已证明达到全局最优。',('The project focuses on route optimization for delivery vehicles.','这个项目重点研究配送车辆的路线优化。'),('We measured the results before and after optimization.','我们测量了优化前后的结果。'),sources=['https://www.etymonline.com/word/optimization','https://en.wiktionary.org/wiki/optimization']),
E('optimisation','英 /ˌɒptɪmaɪˈzeɪʃən/；美 /ˌɑptɪməˈzeɪʃən/','优化〔常见英式拼写〕','在一组限制内，不断比较方案，争取把事情安排得更好。','optimise + -ation；对应 optimization 的 -isation 拼写。',B+[['英语 optimise → optimisation','优化 → 优化这项过程']],'energy optimisation 是优化能源使用；search engine optimisation 指使网页更便于搜索引擎理解和呈现的一类工作。先抓住“针对目标改善安排”，再看具体领域。','process optimisation；energy optimisation；search engine optimisation。','optimisation 与 optimization 是拼写变体；单独这个名词并不告诉你优化的指标是什么。',('The report describes the optimisation of the production schedule.','报告介绍了生产排期的优化。'),('Further optimisation reduced the amount of material wasted.','进一步优化减少了材料浪费。'),sources=['https://en.wiktionary.org/wiki/optimisation','https://www.etymonline.com/word/optimization'])
]
